/**
 * The Tala HTTP API, v1. One table: the server router, the typed client and the tests all read it.
 * Base path: /api/v1. JSON in, JSON out. Errors use `ApiError` (common.ts).
 *
 * Auth: web uses an httpOnly session cookie; mobile sends `Authorization: Bearer <token>`.
 * `owner` names the workstream whose server module implements the handler (docs/tala/ARCHITECTURE.md).
 *
 * OWNER: orchestrator. To change or add a route, ask the orchestrator; do not edit this file in a worker branch.
 */
import { z } from 'zod';
import { Id, IsoDateTime, Lang, Ok, Page, QueryBool } from './common';
import { CalendarPreset, CheckSummary, CurriculumIndex, CurriculumPack } from './curriculum';
import { PackDetail, PackIndex, PackLang } from './packs';
import { DeckCreateRequest, DeckDetail, DeckList, DeckSaveRequest, DeckSaveResult } from './decks';
import {
  ArtifactDetail,
  ArtifactSearchQuery,
  ArtifactSummary,
  ClientConfig,
  CopyArtifactResponse,
  GenerationAllowance,
  GenerationInput,
  GenerationJob,
  ModerationDecision,
  PostArtifactRequest,
  ReportRequest,
  RosterConfirmRequest,
  RosterConfirmResponse,
  RosterField,
  RosterImportDraft,
  RosterImportRequest,
} from './features';
import { PullQuery, PullResponse, PushRequest, PushResponse } from './sync';
import { RecordEnvelopeSchema } from './records';

export const API_BASE = '/api/v1';

/**
 * Paths of the web pages that emailed links open. The token travels in the URL fragment
 * (`<origin>/verify-email#token=…`) so it never reaches an access log; the page reads `location.hash`
 * and posts it to `auth.verifyEmail` / `auth.reset`.
 */
export const MAIL_LINK_PATHS = {
  verifyEmail: '/verify-email',
  resetPassword: '/reset-password',
  /** Posts its fragment token to `auth.googleLinkConfirm`. */
  linkGoogle: '/link-google',
} as const;

export type Owner = 'core' | 'curriculum' | 'generation' | 'roster' | 'community' | 'print' | 'packs' | 'decks';

export interface RouteSpec {
  method: 'GET' | 'POST' | 'PUT' | 'DELETE';
  /** Path under API_BASE, with `:param` segments. */
  path: string;
  auth: 'none' | 'user';
  owner: Owner;
  body?: z.ZodTypeAny;
  query?: z.ZodTypeAny;
  response: z.ZodTypeAny;
  /** Response is a binary body (application/pdf); `response` is ignored for parsing. */
  binary?: boolean;
}

/** `const` type parameter keeps `path` a string literal so ParamsOf<K> can read its `:params`. */
const route = <const S extends RouteSpec>(spec: S): S => spec;

/* ---------- auth DTOs (PRD §13.2, §13.3) ---------- */

export const Password = z.string().min(10).max(200);
export const Email = z.string().email().max(254);

export const User = z.object({
  id: Id,
  email: Email,
  emailVerified: z.boolean(),
  displayName: z.string(),
  hasPassword: z.boolean(),
  hasGoogle: z.boolean(),
  createdAt: IsoDateTime,
});
export type User = z.infer<typeof User>;

export const AuthResult = z.object({
  user: User,
  /** Bearer token for mobile. Web ignores it and relies on the cookie set by the same response. */
  token: z.string(),
  expiresAt: IsoDateTime,
});

export const SessionInfo = z.object({
  id: Id,
  deviceLabel: z.string(),
  createdAt: IsoDateTime,
  lastSeenAt: IsoDateTime,
  current: z.boolean(),
});

export const PlanRevisionMeta = z.object({
  revision: z.number().int(),
  createdAt: IsoDateTime,
  /** 'post_class' = writing in an after-class section of a locked plan (assessment results, reflection). */
  reason: z.enum(['save', 'lock', 'unlock', 'regenerate', 'restore', 'conflict', 'post_class']),
  locked: z.boolean(),
});

/* ---------- the table ---------- */

